  "detail.parameterHelp.settingsPromptPlaceholder.referencePolicy": "`{reference_policy}`：今回の実行に入力画像または参考画像がある場合だけ注入される視覚参照ルールです。参考画像がない場合は空文字列になります。",
  "detail.parameterHelp.settingsPromptPlaceholder.kind": "`{kind}`：メイン画像、ポスター/縦長画像などの出力タイプを区別するバックエンド用途 enum 値です。機械可読な分岐が必要なテンプレートに向いています。",
  "detail.parameterHelp.settingsPromptPlaceholder.kindLabel": "`{kind_label}`：モデル向けの自然言語用途ラベルです。例：主图、促销海报。プロンプト本文にそのまま入れる用途に向いています。",
  "detail.parameterHelp.settingsPromptPlaceholder.kindRequirements": "`{kind_requirements}`：バックエンド生成の用途制約です。出力用途を示し、フィールド名、JSON key、コンテキスト説明、ブランド、透かし、UI パネルを画像に描かないよう指示します。",
  "detail.parameterHelp.settingsPromptPlaceholder.prompt": "`{prompt}`：画像チャットの今回のユーザー画像説明です。通常はテンプレート内に残し、今回の生成または編集の主要求として使います。",
  "detail.parameterHelp.settingsPromptPlaceholder.historyBlock": "`{history_block}`：直近最大 8 件の会話ターンから作られるコンテキストです。利用可能な履歴がある場合だけ注入され、ない場合は空になり、反復会話の一貫性を保つために使います。",
  "detail.parameterHelp.settingsPromptPlaceholder.syntax": "プレースホルダーは単一の波括弧と正確なフィールド名を使います。例：`{instruction}`。二重波括弧や大文字小文字の変更は使わないでください。",
  "detail.parameterHelp.settingsPromptSystem.noPlaceholders": "この設定は system instruction または参照ルール文であり、プレースホルダー置換されません。`{...}` は通常テキストとして送信または注入されます。",
  "detail.parameterHelp.settingsPromptSystem.outputContract": "編集時は JSON-only、補正後プロンプトのみ、分割計画のみなど既存の出力契約を保ち、下流解析を壊さないようにしてください。",
